CREATE TABLE development_program_heads (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-program-head.v1'),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  current_program_version_ref ANY NOT NULL CHECK (typeof(current_program_version_ref)='text' AND length(current_program_version_ref) BETWEEN 1 AND 96 AND substr(current_program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND current_program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(current_program_version_ref,1,instr(current_program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  current_program_version_number ANY NOT NULL CHECK (typeof(current_program_version_number)='integer' AND current_program_version_number>=1),
  head_revision ANY NOT NULL CHECK (typeof(head_revision)='integer' AND head_revision>=0),
  program_state ANY NOT NULL CHECK (typeof(program_state)='text' AND program_state IN ('active','accepted','terminal_rejected','blocked')),
  updated_at ANY NOT NULL CHECK (typeof(updated_at)='text' AND length(updated_at)=20 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(updated_at,1,4) BETWEEN '0001' AND '9999' AND substr(updated_at,6,2) BETWEEN '01' AND '12' AND substr(updated_at,9,2) BETWEEN '01' AND '31' AND substr(updated_at,12,2) BETWEEN '00' AND '23' AND substr(updated_at,15,2) BETWEEN '00' AND '59' AND substr(updated_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at)=updated_at),
  head_digest ANY NOT NULL CHECK (typeof(head_digest)='text' AND length(head_digest)=64 AND head_digest=lower(head_digest) AND head_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (program_ref),
  FOREIGN KEY (program_ref, current_program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE development_program_versions (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-program-version.v1'),
  program_version_ref ANY NOT NULL CHECK (typeof(program_version_ref)='text' AND length(program_version_ref) BETWEEN 1 AND 96 AND substr(program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_version_ref,1,instr(program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_version_number ANY NOT NULL CHECK (typeof(program_version_number)='integer' AND program_version_number>=1),
  program_version_kind ANY NOT NULL CHECK (typeof(program_version_kind)='text' AND program_version_kind IN ('initial','accepted','repair','replan','terminal_rejected','blocked')),
  creating_decision_ref ANY NOT NULL CHECK (typeof(creating_decision_ref)='text' AND length(creating_decision_ref) BETWEEN 1 AND 96 AND substr(creating_decision_ref,1,1) GLOB '[0-9A-Za-z]' AND creating_decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(creating_decision_ref,1,instr(creating_decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  accepted_intent_revision_ref ANY NOT NULL CHECK (typeof(accepted_intent_revision_ref)='text' AND length(accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(accepted_intent_revision_ref,1,instr(accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  created_at ANY NOT NULL CHECK (typeof(created_at)='text' AND length(created_at)=20 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND substr(created_at,6,2) BETWEEN '01' AND '12' AND substr(created_at,9,2) BETWEEN '01' AND '31' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at)=created_at),
  program_version_digest ANY NOT NULL CHECK (typeof(program_version_digest)='text' AND length(program_version_digest)=64 AND program_version_digest=lower(program_version_digest) AND program_version_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (program_version_ref),
  UNIQUE (program_ref, program_version_ref),
  UNIQUE (program_ref, program_version_number),
  CONSTRAINT initial_program_version_number CHECK (((program_version_kind='initial' AND program_version_number=1) OR (program_version_kind<>'initial' AND program_version_number>=2))),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, creating_decision_ref) REFERENCES development_decisions (program_ref, decision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE development_accepted_intent_revisions (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-accepted-intent-revision.v1'),
  accepted_intent_revision_ref ANY NOT NULL CHECK (typeof(accepted_intent_revision_ref)='text' AND length(accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(accepted_intent_revision_ref,1,instr(accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  accepted_intent_revision_number ANY NOT NULL CHECK (typeof(accepted_intent_revision_number)='integer' AND accepted_intent_revision_number>=1),
  prior_accepted_intent_revision_ref ANY CHECK (prior_accepted_intent_revision_ref IS NULL OR (typeof(prior_accepted_intent_revision_ref)='text' AND length(prior_accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(prior_accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND prior_accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(prior_accepted_intent_revision_ref,1,instr(prior_accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  source_intent_ref ANY NOT NULL CHECK (typeof(source_intent_ref)='text' AND length(source_intent_ref) BETWEEN 1 AND 96 AND substr(source_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND source_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(source_intent_ref,1,instr(source_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  source_intent_digest ANY NOT NULL CHECK (typeof(source_intent_digest)='text' AND length(source_intent_digest)=64 AND source_intent_digest=lower(source_intent_digest) AND source_intent_digest NOT GLOB '*[^0-9a-f]*'),
  safe_projection_digest ANY NOT NULL CHECK (typeof(safe_projection_digest)='text' AND length(safe_projection_digest)=64 AND safe_projection_digest=lower(safe_projection_digest) AND safe_projection_digest NOT GLOB '*[^0-9a-f]*'),
  created_at ANY NOT NULL CHECK (typeof(created_at)='text' AND length(created_at)=20 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND substr(created_at,6,2) BETWEEN '01' AND '12' AND substr(created_at,9,2) BETWEEN '01' AND '31' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at)=created_at),
  accepted_intent_revision_digest ANY NOT NULL CHECK (typeof(accepted_intent_revision_digest)='text' AND length(accepted_intent_revision_digest)=64 AND accepted_intent_revision_digest=lower(accepted_intent_revision_digest) AND accepted_intent_revision_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (accepted_intent_revision_ref),
  UNIQUE (program_ref, accepted_intent_revision_ref),
  UNIQUE (program_ref, accepted_intent_revision_number),
  CONSTRAINT accepted_intent_prior_bidirectional CHECK (((accepted_intent_revision_number=1 AND prior_accepted_intent_revision_ref IS NULL) OR (accepted_intent_revision_number>=2 AND prior_accepted_intent_revision_ref IS NOT NULL))),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, prior_accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

CREATE TABLE development_work_item_heads (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-work-item-head.v1'),
  work_item_ref ANY NOT NULL CHECK (typeof(work_item_ref)='text' AND length(work_item_ref) BETWEEN 1 AND 96 AND substr(work_item_ref,1,1) GLOB '[0-9A-Za-z]' AND work_item_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(work_item_ref,1,instr(work_item_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  current_work_item_revision_ref ANY NOT NULL CHECK (typeof(current_work_item_revision_ref)='text' AND length(current_work_item_revision_ref) BETWEEN 1 AND 96 AND substr(current_work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND current_work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(current_work_item_revision_ref,1,instr(current_work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  current_work_item_revision_number ANY NOT NULL CHECK (typeof(current_work_item_revision_number)='integer' AND current_work_item_revision_number>=1),
  head_revision ANY NOT NULL CHECK (typeof(head_revision)='integer' AND head_revision>=0),
  work_state ANY NOT NULL CHECK (typeof(work_state)='text' AND work_state IN ('planned','active','accepted','repair_required','terminal_rejected','blocked')),
  updated_at ANY NOT NULL CHECK (typeof(updated_at)='text' AND length(updated_at)=20 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(updated_at,1,4) BETWEEN '0001' AND '9999' AND substr(updated_at,6,2) BETWEEN '01' AND '12' AND substr(updated_at,9,2) BETWEEN '01' AND '31' AND substr(updated_at,12,2) BETWEEN '00' AND '23' AND substr(updated_at,15,2) BETWEEN '00' AND '59' AND substr(updated_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at)=updated_at),
  head_digest ANY NOT NULL CHECK (typeof(head_digest)='text' AND length(head_digest)=64 AND head_digest=lower(head_digest) AND head_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (work_item_ref),
  UNIQUE (program_ref, work_item_ref),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, work_item_ref, current_work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE development_work_item_revisions (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-work-item-revision.v1'),
  work_item_revision_ref ANY NOT NULL CHECK (typeof(work_item_revision_ref)='text' AND length(work_item_revision_ref) BETWEEN 1 AND 96 AND substr(work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(work_item_revision_ref,1,instr(work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  work_item_ref ANY NOT NULL CHECK (typeof(work_item_ref)='text' AND length(work_item_ref) BETWEEN 1 AND 96 AND substr(work_item_ref,1,1) GLOB '[0-9A-Za-z]' AND work_item_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(work_item_ref,1,instr(work_item_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  work_item_revision_number ANY NOT NULL CHECK (typeof(work_item_revision_number)='integer' AND work_item_revision_number>=1),
  work_item_revision_kind ANY NOT NULL CHECK (typeof(work_item_revision_kind)='text' AND work_item_revision_kind IN ('initial','replan')),
  prior_work_item_revision_ref ANY CHECK (prior_work_item_revision_ref IS NULL OR (typeof(prior_work_item_revision_ref)='text' AND length(prior_work_item_revision_ref) BETWEEN 1 AND 96 AND substr(prior_work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND prior_work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(prior_work_item_revision_ref,1,instr(prior_work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  accepted_intent_revision_ref ANY NOT NULL CHECK (typeof(accepted_intent_revision_ref)='text' AND length(accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(accepted_intent_revision_ref,1,instr(accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  created_at ANY NOT NULL CHECK (typeof(created_at)='text' AND length(created_at)=20 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND substr(created_at,6,2) BETWEEN '01' AND '12' AND substr(created_at,9,2) BETWEEN '01' AND '31' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at)=created_at),
  work_item_revision_digest ANY NOT NULL CHECK (typeof(work_item_revision_digest)='text' AND length(work_item_revision_digest)=64 AND work_item_revision_digest=lower(work_item_revision_digest) AND work_item_revision_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (work_item_revision_ref),
  UNIQUE (program_ref, work_item_ref, work_item_revision_ref),
  UNIQUE (program_ref, work_item_revision_ref),
  UNIQUE (program_ref, work_item_ref, work_item_revision_number),
  CONSTRAINT work_revision_prior_bidirectional CHECK (((work_item_revision_kind='initial' AND work_item_revision_number=1 AND prior_work_item_revision_ref IS NULL) OR (work_item_revision_kind='replan' AND work_item_revision_number>=2 AND prior_work_item_revision_ref IS NOT NULL))),
  FOREIGN KEY (program_ref, work_item_ref) REFERENCES development_work_item_heads (program_ref, work_item_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, work_item_ref, prior_work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

