  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_version_ref ANY NOT NULL CHECK (typeof(program_version_ref)='text' AND length(program_version_ref) BETWEEN 1 AND 96 AND substr(program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_version_ref,1,instr(program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  work_item_ref ANY NOT NULL CHECK (typeof(work_item_ref)='text' AND length(work_item_ref) BETWEEN 1 AND 96 AND substr(work_item_ref,1,1) GLOB '[0-9A-Za-z]' AND work_item_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(work_item_ref,1,instr(work_item_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  work_item_revision_ref ANY NOT NULL CHECK (typeof(work_item_revision_ref)='text' AND length(work_item_revision_ref) BETWEEN 1 AND 96 AND substr(work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(work_item_revision_ref,1,instr(work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
