  membership_digest ANY NOT NULL CHECK (typeof(membership_digest)='text' AND length(membership_digest)=64 AND membership_digest=lower(membership_digest) AND membership_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (program_ref, program_version_ref, work_item_ref),
  UNIQUE (program_ref, program_version_ref, membership_ordinal),
  FOREIGN KEY (program_ref, program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, work_item_ref, work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

CREATE TABLE development_revision_edges (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-revision-edge.v1'),
  revision_edge_ref ANY NOT NULL CHECK (typeof(revision_edge_ref)='text' AND length(revision_edge_ref) BETWEEN 1 AND 96 AND substr(revision_edge_ref,1,1) GLOB '[0-9A-Za-z]' AND revision_edge_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(revision_edge_ref,1,instr(revision_edge_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  relation_key_digest ANY NOT NULL CHECK (typeof(relation_key_digest)='text' AND length(relation_key_digest)=64 AND relation_key_digest=lower(relation_key_digest) AND relation_key_digest NOT GLOB '*[^0-9a-f]*'),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  revision_edge_kind ANY NOT NULL CHECK (typeof(revision_edge_kind)='text' AND revision_edge_kind IN ('accepted_intent_supersedes','work_item_supersedes','work_item_split','work_item_merge')),
  from_accepted_intent_revision_ref ANY CHECK (from_accepted_intent_revision_ref IS NULL OR (typeof(from_accepted_intent_revision_ref)='text' AND length(from_accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(from_accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND from_accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(from_accepted_intent_revision_ref,1,instr(from_accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  to_accepted_intent_revision_ref ANY CHECK (to_accepted_intent_revision_ref IS NULL OR (typeof(to_accepted_intent_revision_ref)='text' AND length(to_accepted_intent_revision_ref) BETWEEN 1 AND 96 AND substr(to_accepted_intent_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND to_accepted_intent_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(to_accepted_intent_revision_ref,1,instr(to_accepted_intent_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  from_work_item_revision_ref ANY CHECK (from_work_item_revision_ref IS NULL OR (typeof(from_work_item_revision_ref)='text' AND length(from_work_item_revision_ref) BETWEEN 1 AND 96 AND substr(from_work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND from_work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(from_work_item_revision_ref,1,instr(from_work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  to_work_item_revision_ref ANY CHECK (to_work_item_revision_ref IS NULL OR (typeof(to_work_item_revision_ref)='text' AND length(to_work_item_revision_ref) BETWEEN 1 AND 96 AND substr(to_work_item_revision_ref,1,1) GLOB '[0-9A-Za-z]' AND to_work_item_revision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(to_work_item_revision_ref,1,instr(to_work_item_revision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  created_at ANY NOT NULL CHECK (typeof(created_at)='text' AND length(created_at)=20 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND substr(created_at,6,2) BETWEEN '01' AND '12' AND substr(created_at,9,2) BETWEEN '01' AND '31' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at)=created_at),
  revision_edge_digest ANY NOT NULL CHECK (typeof(revision_edge_digest)='text' AND length(revision_edge_digest)=64 AND revision_edge_digest=lower(revision_edge_digest) AND revision_edge_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (revision_edge_ref),
  UNIQUE (relation_key_digest),
  CONSTRAINT revision_edge_endpoint_algebra CHECK (((revision_edge_kind='accepted_intent_supersedes' AND from_accepted_intent_revision_ref IS NOT NULL AND to_accepted_intent_revision_ref IS NOT NULL AND from_work_item_revision_ref IS NULL AND to_work_item_revision_ref IS NULL) OR (revision_edge_kind IN ('work_item_supersedes','work_item_split','work_item_merge') AND from_accepted_intent_revision_ref IS NULL AND to_accepted_intent_revision_ref IS NULL AND from_work_item_revision_ref IS NOT NULL AND to_work_item_revision_ref IS NOT NULL))),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, from_accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, to_accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, from_work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, to_work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

