  semantic_attempt_digest ANY NOT NULL CHECK (typeof(semantic_attempt_digest)='text' AND length(semantic_attempt_digest)=64 AND semantic_attempt_digest=lower(semantic_attempt_digest) AND semantic_attempt_digest NOT GLOB '*[^0-9a-f]*'),
