  aggregate_max_memory_bytes ANY NOT NULL CHECK (typeof(aggregate_max_memory_bytes)='integer' AND aggregate_max_memory_bytes>=0),
  aggregate_max_merges ANY NOT NULL CHECK (typeof(aggregate_max_merges)='integer' AND aggregate_max_merges>=0),
  aggregate_max_model_input_tokens ANY NOT NULL CHECK (typeof(aggregate_max_model_input_tokens)='integer' AND aggregate_max_model_input_tokens>=0),
  aggregate_max_model_output_tokens ANY NOT NULL CHECK (typeof(aggregate_max_model_output_tokens)='integer' AND aggregate_max_model_output_tokens>=0),
  aggregate_max_pull_requests ANY NOT NULL CHECK (typeof(aggregate_max_pull_requests)='integer' AND aggregate_max_pull_requests>=0),
  aggregate_max_pushes ANY NOT NULL CHECK (typeof(aggregate_max_pushes)='integer' AND aggregate_max_pushes>=0),
  aggregate_max_wall_seconds ANY NOT NULL CHECK (typeof(aggregate_max_wall_seconds)='integer' AND aggregate_max_wall_seconds>=0),
  expires_at ANY NOT NULL CHECK (typeof(expires_at)='text' AND length(expires_at)=20 AND expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(expires_at,1,4) BETWEEN '0001' AND '9999' AND substr(expires_at,6,2) BETWEEN '01' AND '12' AND substr(expires_at,9,2) BETWEEN '01' AND '31' AND substr(expires_at,12,2) BETWEEN '00' AND '23' AND substr(expires_at,15,2) BETWEEN '00' AND '59' AND substr(expires_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',expires_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',expires_at)=expires_at),
  global_stop_ref ANY NOT NULL CHECK (typeof(global_stop_ref)='text' AND length(global_stop_ref) BETWEEN 1 AND 96 AND substr(global_stop_ref,1,1) GLOB '[0-9A-Za-z]' AND global_stop_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(global_stop_ref,1,instr(global_stop_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  global_stop_version ANY NOT NULL CHECK (typeof(global_stop_version)='integer' AND global_stop_version>=0),
  attempt_fence_digest ANY NOT NULL CHECK (typeof(attempt_fence_digest)='text' AND length(attempt_fence_digest)=64 AND attempt_fence_digest=lower(attempt_fence_digest) AND attempt_fence_digest NOT GLOB '*[^0-9a-f]*'),
  recorded_at ANY NOT NULL CHECK (typeof(recorded_at)='text' AND length(recorded_at)=20 AND recorded_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(recorded_at,1,4) BETWEEN '0001' AND '9999' AND substr(recorded_at,6,2) BETWEEN '01' AND '12' AND substr(recorded_at,9,2) BETWEEN '01' AND '31' AND substr(recorded_at,12,2) BETWEEN '00' AND '23' AND substr(recorded_at,15,2) BETWEEN '00' AND '59' AND substr(recorded_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',recorded_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',recorded_at)=recorded_at),
  PRIMARY KEY (attempt_fence_ref),
  UNIQUE (program_ref, attempt_fence_ref),
  UNIQUE (program_ref, semantic_attempt_ref),
  FOREIGN KEY (program_ref, program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, accepted_intent_revision_ref) REFERENCES development_accepted_intent_revisions (program_ref, accepted_intent_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, work_item_ref, work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

CREATE TABLE development_authority_evaluations (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-authority-evaluation.v1'),
  authority_evaluation_ref ANY NOT NULL CHECK (typeof(authority_evaluation_ref)='text' AND length(authority_evaluation_ref) BETWEEN 1 AND 96 AND substr(authority_evaluation_ref,1,1) GLOB '[0-9A-Za-z]' AND authority_evaluation_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(authority_evaluation_ref,1,instr(authority_evaluation_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  evaluation_scope ANY NOT NULL CHECK (typeof(evaluation_scope)='text' AND evaluation_scope IN ('attempt','effect')),
  evaluation_subject_ref ANY NOT NULL CHECK (typeof(evaluation_subject_ref)='text' AND length(evaluation_subject_ref) BETWEEN 1 AND 96 AND substr(evaluation_subject_ref,1,1) GLOB '[0-9A-Za-z]' AND evaluation_subject_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(evaluation_subject_ref,1,instr(evaluation_subject_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  semantic_attempt_ref ANY CHECK (semantic_attempt_ref IS NULL OR (typeof(semantic_attempt_ref)='text' AND length(semantic_attempt_ref) BETWEEN 1 AND 96 AND substr(semantic_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND semantic_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(semantic_attempt_ref,1,instr(semantic_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  effect_intent_ref ANY CHECK (effect_intent_ref IS NULL OR (typeof(effect_intent_ref)='text' AND length(effect_intent_ref) BETWEEN 1 AND 96 AND substr(effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(effect_intent_ref,1,instr(effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  authority_ref ANY NOT NULL CHECK (typeof(authority_ref)='text' AND length(authority_ref) BETWEEN 1 AND 96 AND substr(authority_ref,1,1) GLOB '[0-9A-Za-z]' AND authority_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(authority_ref,1,instr(authority_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  authority_digest ANY NOT NULL CHECK (typeof(authority_digest)='text' AND length(authority_digest)=64 AND authority_digest=lower(authority_digest) AND authority_digest NOT GLOB '*[^0-9a-f]*'),
  authority_state ANY NOT NULL CHECK (typeof(authority_state)='text' AND authority_state IN ('pending','verified','blocked','stale','revoked','expired')),
  reason_code ANY NOT NULL CHECK (typeof(reason_code)='text' AND length(reason_code) BETWEEN 1 AND 96 AND substr(reason_code,1,1) GLOB '[a-z]' AND reason_code NOT GLOB '*[^a-z0-9_.-]*'),
  expires_at ANY CHECK (expires_at IS NULL OR (typeof(expires_at)='text' AND length(expires_at)=20 AND expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(expires_at,1,4) BETWEEN '0001' AND '9999' AND substr(expires_at,6,2) BETWEEN '01' AND '12' AND substr(expires_at,9,2) BETWEEN '01' AND '31' AND substr(expires_at,12,2) BETWEEN '00' AND '23' AND substr(expires_at,15,2) BETWEEN '00' AND '59' AND substr(expires_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',expires_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',expires_at)=expires_at)),
  evaluated_at ANY NOT NULL CHECK (typeof(evaluated_at)='text' AND length(evaluated_at)=20 AND evaluated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(evaluated_at,1,4) BETWEEN '0001' AND '9999' AND substr(evaluated_at,6,2) BETWEEN '01' AND '12' AND substr(evaluated_at,9,2) BETWEEN '01' AND '31' AND substr(evaluated_at,12,2) BETWEEN '00' AND '23' AND substr(evaluated_at,15,2) BETWEEN '00' AND '59' AND substr(evaluated_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',evaluated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',evaluated_at)=evaluated_at),
  authority_evaluation_digest ANY NOT NULL CHECK (typeof(authority_evaluation_digest)='text' AND length(authority_evaluation_digest)=64 AND authority_evaluation_digest=lower(authority_evaluation_digest) AND authority_evaluation_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (authority_evaluation_ref),
  UNIQUE (program_ref, authority_evaluation_ref),
  CONSTRAINT authority_scope_subject_algebra CHECK (((evaluation_scope='attempt' AND semantic_attempt_ref IS NOT NULL AND effect_intent_ref IS NULL AND evaluation_subject_ref=semantic_attempt_ref) OR (evaluation_scope='effect' AND semantic_attempt_ref IS NULL AND effect_intent_ref IS NOT NULL AND evaluation_subject_ref=effect_intent_ref))),
  CONSTRAINT authority_expiry_algebra CHECK (((authority_state IN ('verified','expired') AND expires_at IS NOT NULL) OR (authority_state IN ('pending','blocked','stale','revoked') AND expires_at IS NULL))),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

CREATE TABLE development_effect_intents (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-effect-intent.v1'),
  effect_intent_ref ANY NOT NULL CHECK (typeof(effect_intent_ref)='text' AND length(effect_intent_ref) BETWEEN 1 AND 96 AND substr(effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(effect_intent_ref,1,instr(effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_version_ref ANY NOT NULL CHECK (typeof(program_version_ref)='text' AND length(program_version_ref) BETWEEN 1 AND 96 AND substr(program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_version_ref,1,instr(program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  semantic_attempt_ref ANY NOT NULL CHECK (typeof(semantic_attempt_ref)='text' AND length(semantic_attempt_ref) BETWEEN 1 AND 96 AND substr(semantic_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND semantic_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(semantic_attempt_ref,1,instr(semantic_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  effect_class ANY NOT NULL CHECK (typeof(effect_class)='text' AND effect_class IN ('author_candidate','cancel_effect','local_git_commit','review_candidate','validate_candidate')),
  candidate_ref ANY NOT NULL CHECK (typeof(candidate_ref)='text' AND length(candidate_ref) BETWEEN 1 AND 96 AND substr(candidate_ref,1,1) GLOB '[0-9A-Za-z]' AND candidate_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(candidate_ref,1,instr(candidate_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  command_ref ANY NOT NULL CHECK (typeof(command_ref)='text' AND length(command_ref) BETWEEN 1 AND 96 AND substr(command_ref,1,1) GLOB '[0-9A-Za-z]' AND command_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(command_ref,1,instr(command_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  basis_decision_ref ANY NOT NULL CHECK (typeof(basis_decision_ref)='text' AND length(basis_decision_ref) BETWEEN 1 AND 96 AND substr(basis_decision_ref,1,1) GLOB '[0-9A-Za-z]' AND basis_decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(basis_decision_ref,1,instr(basis_decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  cancellation_target_effect_intent_ref ANY CHECK (cancellation_target_effect_intent_ref IS NULL OR (typeof(cancellation_target_effect_intent_ref)='text' AND length(cancellation_target_effect_intent_ref) BETWEEN 1 AND 96 AND substr(cancellation_target_effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND cancellation_target_effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(cancellation_target_effect_intent_ref,1,instr(cancellation_target_effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  expected_target_effect_head_revision ANY CHECK (expected_target_effect_head_revision IS NULL OR (typeof(expected_target_effect_head_revision)='integer' AND expected_target_effect_head_revision>=0)),
  portable_capsule_digest ANY CHECK (portable_capsule_digest IS NULL OR (typeof(portable_capsule_digest)='text' AND length(portable_capsule_digest)=64 AND portable_capsule_digest=lower(portable_capsule_digest) AND portable_capsule_digest NOT GLOB '*[^0-9a-f]*')),
  created_at ANY NOT NULL CHECK (typeof(created_at)='text' AND length(created_at)=20 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND substr(created_at,6,2) BETWEEN '01' AND '12' AND substr(created_at,9,2) BETWEEN '01' AND '31' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',created_at)=created_at),
  effect_intent_digest ANY NOT NULL CHECK (typeof(effect_intent_digest)='text' AND length(effect_intent_digest)=64 AND effect_intent_digest=lower(effect_intent_digest) AND effect_intent_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (effect_intent_ref),
  UNIQUE (program_ref, effect_intent_ref),
  CONSTRAINT effect_intent_cancellation_algebra CHECK (((effect_class='cancel_effect' AND cancellation_target_effect_intent_ref IS NOT NULL AND expected_target_effect_head_revision IS NOT NULL) OR (effect_class<>'cancel_effect' AND cancellation_target_effect_intent_ref IS NULL AND expected_target_effect_head_revision IS NULL))),
  CONSTRAINT effect_intent_capsule_algebra CHECK (((effect_class='author_candidate' AND portable_capsule_digest IS NULL) OR (effect_class IN ('validate_candidate','review_candidate','local_git_commit') AND portable_capsule_digest IS NOT NULL) OR effect_class='cancel_effect')),
  FOREIGN KEY (program_ref, program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (basis_decision_ref) REFERENCES development_decisions (decision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, command_ref) REFERENCES development_author_commands (program_ref, command_ref) ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (program_ref, cancellation_target_effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

