  command_ref ANY NOT NULL CHECK (typeof(command_ref)='text' AND length(command_ref) BETWEEN 1 AND 96 AND substr(command_ref,1,1) GLOB '[0-9A-Za-z]' AND command_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(command_ref,1,instr(command_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
