  path_ceiling_json ANY NOT NULL CHECK (typeof(path_ceiling_json)='text' AND path_ceiling_json='[".docs/system_overview/hybrid_integration_architecture_adr.md","PLANS.md","docs_contract_test.go"]'),
  effect_max_active_invocations ANY NOT NULL CHECK (typeof(effect_max_active_invocations)='integer' AND effect_max_active_invocations>=0),
