  CONSTRAINT effect_fence_capsule_algebra CHECK (((effect_class='author_candidate' AND portable_capsule_digest IS NULL) OR (effect_class IN ('validate_candidate','review_candidate','local_git_commit') AND portable_capsule_digest IS NOT NULL) OR effect_class='cancel_effect')),
  FOREIGN KEY (program_ref, program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
