  FOREIGN KEY (program_ref, work_item_ref, work_item_revision_ref) REFERENCES development_work_item_revisions (program_ref, work_item_ref, work_item_revision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, attempt_fence_ref) REFERENCES development_attempt_fences (program_ref, attempt_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, effect_fence_ref) REFERENCES development_effect_fences (program_ref, effect_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
