CREATE TABLE development_effect_heads (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-effect-head.v1'),
  effect_intent_ref ANY NOT NULL CHECK (typeof(effect_intent_ref)='text' AND length(effect_intent_ref) BETWEEN 1 AND 96 AND substr(effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(effect_intent_ref,1,instr(effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  current_effect_fence_ref ANY NOT NULL CHECK (typeof(current_effect_fence_ref)='text' AND length(current_effect_fence_ref) BETWEEN 1 AND 96 AND substr(current_effect_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND current_effect_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(current_effect_fence_ref,1,instr(current_effect_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  head_revision ANY NOT NULL CHECK (typeof(head_revision)='integer' AND head_revision>=0),
  effect_state ANY NOT NULL CHECK (typeof(effect_state)='text' AND effect_state IN ('ready_for_delivery','delivery_pending','delivery_outcome_unknown','observed','cancellation_effect_established','terminal')),
  cancellation_effect_intent_ref ANY CHECK (cancellation_effect_intent_ref IS NULL OR (typeof(cancellation_effect_intent_ref)='text' AND length(cancellation_effect_intent_ref) BETWEEN 1 AND 96 AND substr(cancellation_effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND cancellation_effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(cancellation_effect_intent_ref,1,instr(cancellation_effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  updated_at ANY NOT NULL CHECK (typeof(updated_at)='text' AND length(updated_at)=20 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(updated_at,1,4) BETWEEN '0001' AND '9999' AND substr(updated_at,6,2) BETWEEN '01' AND '12' AND substr(updated_at,9,2) BETWEEN '01' AND '31' AND substr(updated_at,12,2) BETWEEN '00' AND '23' AND substr(updated_at,15,2) BETWEEN '00' AND '59' AND substr(updated_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',updated_at)=updated_at),
  head_digest ANY NOT NULL CHECK (typeof(head_digest)='text' AND length(head_digest)=64 AND head_digest=lower(head_digest) AND head_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (effect_intent_ref),
  UNIQUE (program_ref, effect_intent_ref),
  CONSTRAINT effect_head_cancellation_algebra CHECK (((effect_state='cancellation_effect_established' AND cancellation_effect_intent_ref IS NOT NULL) OR (effect_state<>'cancellation_effect_established' AND cancellation_effect_intent_ref IS NULL))),
  FOREIGN KEY (program_ref, effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, current_effect_fence_ref) REFERENCES development_effect_fences (program_ref, effect_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, cancellation_effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

