  program_version_ref ANY NOT NULL CHECK (typeof(program_version_ref)='text' AND length(program_version_ref) BETWEEN 1 AND 96 AND substr(program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_version_ref,1,instr(program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  command_ref ANY NOT NULL CHECK (typeof(command_ref)='text' AND length(command_ref) BETWEEN 1 AND 96 AND substr(command_ref,1,1) GLOB '[0-9A-Za-z]' AND command_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(command_ref,1,instr(command_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  command_digest ANY NOT NULL CHECK (typeof(command_digest)='text' AND length(command_digest)=64 AND command_digest=lower(command_digest) AND command_digest NOT GLOB '*[^0-9a-f]*'),
  semantic_attempt_ref ANY NOT NULL CHECK (typeof(semantic_attempt_ref)='text' AND length(semantic_attempt_ref) BETWEEN 1 AND 96 AND substr(semantic_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND semantic_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(semantic_attempt_ref,1,instr(semantic_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  effect_intent_ref ANY NOT NULL CHECK (typeof(effect_intent_ref)='text' AND length(effect_intent_ref) BETWEEN 1 AND 96 AND substr(effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(effect_intent_ref,1,instr(effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  attempt_fence_ref ANY NOT NULL CHECK (typeof(attempt_fence_ref)='text' AND length(attempt_fence_ref) BETWEEN 1 AND 96 AND substr(attempt_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND attempt_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(attempt_fence_ref,1,instr(attempt_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  attempt_fence_digest ANY NOT NULL CHECK (typeof(attempt_fence_digest)='text' AND length(attempt_fence_digest)=64 AND attempt_fence_digest=lower(attempt_fence_digest) AND attempt_fence_digest NOT GLOB '*[^0-9a-f]*'),
  effect_fence_ref ANY NOT NULL CHECK (typeof(effect_fence_ref)='text' AND length(effect_fence_ref) BETWEEN 1 AND 96 AND substr(effect_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND effect_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(effect_fence_ref,1,instr(effect_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  effect_fence_digest ANY NOT NULL CHECK (typeof(effect_fence_digest)='text' AND length(effect_fence_digest)=64 AND effect_fence_digest=lower(effect_fence_digest) AND effect_fence_digest NOT GLOB '*[^0-9a-f]*'),
  adapter_kind ANY NOT NULL CHECK (typeof(adapter_kind)='text' AND adapter_kind IN ('direct_local_bootstrap','execution_substrate')),
  adapter_safe_correlation_ref ANY NOT NULL CHECK (typeof(adapter_safe_correlation_ref)='text' AND length(adapter_safe_correlation_ref) BETWEEN 1 AND 96 AND substr(adapter_safe_correlation_ref,1,1) GLOB '[0-9A-Za-z]' AND adapter_safe_correlation_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(adapter_safe_correlation_ref,1,instr(adapter_safe_correlation_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  delivery_envelope_digest ANY NOT NULL CHECK (typeof(delivery_envelope_digest)='text' AND length(delivery_envelope_digest)=64 AND delivery_envelope_digest=lower(delivery_envelope_digest) AND delivery_envelope_digest NOT GLOB '*[^0-9a-f]*'),
  delivery_kind ANY NOT NULL CHECK (typeof(delivery_kind)='text' AND delivery_kind IN ('initial','redelivery')),
  delivery_number ANY NOT NULL CHECK (typeof(delivery_number)='integer' AND delivery_number>=1),
  predecessor_delivery_attempt_ref ANY CHECK (predecessor_delivery_attempt_ref IS NULL OR (typeof(predecessor_delivery_attempt_ref)='text' AND length(predecessor_delivery_attempt_ref) BETWEEN 1 AND 96 AND substr(predecessor_delivery_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND predecessor_delivery_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(predecessor_delivery_attempt_ref,1,instr(predecessor_delivery_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  basis_decision_ref ANY NOT NULL CHECK (typeof(basis_decision_ref)='text' AND length(basis_decision_ref) BETWEEN 1 AND 96 AND substr(basis_decision_ref,1,1) GLOB '[0-9A-Za-z]' AND basis_decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(basis_decision_ref,1,instr(basis_decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  recorded_at ANY NOT NULL CHECK (typeof(recorded_at)='text' AND length(recorded_at)=20 AND recorded_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(recorded_at,1,4) BETWEEN '0001' AND '9999' AND substr(recorded_at,6,2) BETWEEN '01' AND '12' AND substr(recorded_at,9,2) BETWEEN '01' AND '31' AND substr(recorded_at,12,2) BETWEEN '00' AND '23' AND substr(recorded_at,15,2) BETWEEN '00' AND '59' AND substr(recorded_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',recorded_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',recorded_at)=recorded_at),
  delivery_attempt_digest ANY NOT NULL CHECK (typeof(delivery_attempt_digest)='text' AND length(delivery_attempt_digest)=64 AND delivery_attempt_digest=lower(delivery_attempt_digest) AND delivery_attempt_digest NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (delivery_attempt_ref),
  UNIQUE (program_ref, delivery_attempt_ref),
  UNIQUE (program_ref, effect_intent_ref, delivery_number),
  CONSTRAINT delivery_predecessor_algebra CHECK (((delivery_kind='initial' AND delivery_number=1 AND predecessor_delivery_attempt_ref IS NULL) OR (delivery_kind='redelivery' AND delivery_number>=2 AND predecessor_delivery_attempt_ref IS NOT NULL))),
  FOREIGN KEY (program_ref, program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, command_ref) REFERENCES development_author_commands (program_ref, command_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, attempt_fence_ref) REFERENCES development_attempt_fences (program_ref, attempt_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, effect_fence_ref) REFERENCES development_effect_fences (program_ref, effect_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, predecessor_delivery_attempt_ref) REFERENCES development_delivery_attempts (program_ref, delivery_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, basis_decision_ref) REFERENCES development_decisions (program_ref, decision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

