) STRICT;

CREATE TABLE development_decisions (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-decision.v1'),
  mutation_ref ANY NOT NULL CHECK (typeof(mutation_ref)='text' AND length(mutation_ref) BETWEEN 1 AND 96 AND substr(mutation_ref,1,1) GLOB '[0-9A-Za-z]' AND mutation_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(mutation_ref,1,instr(mutation_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  decision_ref ANY NOT NULL CHECK (typeof(decision_ref)='text' AND length(decision_ref) BETWEEN 1 AND 96 AND substr(decision_ref,1,1) GLOB '[0-9A-Za-z]' AND decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(decision_ref,1,instr(decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  decision_kind ANY NOT NULL CHECK (typeof(decision_kind)='text' AND decision_kind IN ('initialize','accept','repair','replan','terminal_reject','block','redeliver','cancel')),
  decision_variant ANY NOT NULL CHECK (typeof(decision_variant)='text' AND decision_variant IN ('program_genesis','candidate_acceptance','candidate_repair','program_replan','attempt_selecting_replan','program_terminal_reject','program_block','productive_redelivery','cancellation_redelivery','effect_cancellation')),
  basis_decision_ref ANY CHECK (basis_decision_ref IS NULL OR (typeof(basis_decision_ref)='text' AND length(basis_decision_ref) BETWEEN 1 AND 96 AND substr(basis_decision_ref,1,1) GLOB '[0-9A-Za-z]' AND basis_decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(basis_decision_ref,1,instr(basis_decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  basis_program_version_ref ANY CHECK (basis_program_version_ref IS NULL OR (typeof(basis_program_version_ref)='text' AND length(basis_program_version_ref) BETWEEN 1 AND 96 AND substr(basis_program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND basis_program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(basis_program_version_ref,1,instr(basis_program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  basis_program_version_number ANY CHECK (basis_program_version_number IS NULL OR (typeof(basis_program_version_number)='integer' AND basis_program_version_number>=1)),
  expected_program_head_revision ANY NOT NULL CHECK (typeof(expected_program_head_revision)='integer' AND expected_program_head_revision>=0),
  resulting_program_version_ref ANY CHECK (resulting_program_version_ref IS NULL OR (typeof(resulting_program_version_ref)='text' AND length(resulting_program_version_ref) BETWEEN 1 AND 96 AND substr(resulting_program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND resulting_program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(resulting_program_version_ref,1,instr(resulting_program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  resulting_program_version_number ANY CHECK (resulting_program_version_number IS NULL OR (typeof(resulting_program_version_number)='integer' AND resulting_program_version_number>=1)),
  selected_semantic_attempt_ref ANY CHECK (selected_semantic_attempt_ref IS NULL OR (typeof(selected_semantic_attempt_ref)='text' AND length(selected_semantic_attempt_ref) BETWEEN 1 AND 96 AND substr(selected_semantic_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND selected_semantic_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(selected_semantic_attempt_ref,1,instr(selected_semantic_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  selected_candidate_ref ANY CHECK (selected_candidate_ref IS NULL OR (typeof(selected_candidate_ref)='text' AND length(selected_candidate_ref) BETWEEN 1 AND 96 AND substr(selected_candidate_ref,1,1) GLOB '[0-9A-Za-z]' AND selected_candidate_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(selected_candidate_ref,1,instr(selected_candidate_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  selected_attempt_fence_ref ANY CHECK (selected_attempt_fence_ref IS NULL OR (typeof(selected_attempt_fence_ref)='text' AND length(selected_attempt_fence_ref) BETWEEN 1 AND 96 AND substr(selected_attempt_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND selected_attempt_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(selected_attempt_fence_ref,1,instr(selected_attempt_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  selected_attempt_fence_digest ANY CHECK (selected_attempt_fence_digest IS NULL OR (typeof(selected_attempt_fence_digest)='text' AND length(selected_attempt_fence_digest)=64 AND selected_attempt_fence_digest=lower(selected_attempt_fence_digest) AND selected_attempt_fence_digest NOT GLOB '*[^0-9a-f]*')),
  target_effect_intent_ref ANY CHECK (target_effect_intent_ref IS NULL OR (typeof(target_effect_intent_ref)='text' AND length(target_effect_intent_ref) BETWEEN 1 AND 96 AND substr(target_effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND target_effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(target_effect_intent_ref,1,instr(target_effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  target_effect_class ANY CHECK (target_effect_class IS NULL OR (typeof(target_effect_class)='text' AND target_effect_class IN ('author_candidate','cancel_effect','local_git_commit','review_candidate','validate_candidate'))),
  target_effect_fence_ref ANY CHECK (target_effect_fence_ref IS NULL OR (typeof(target_effect_fence_ref)='text' AND length(target_effect_fence_ref) BETWEEN 1 AND 96 AND substr(target_effect_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND target_effect_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(target_effect_fence_ref,1,instr(target_effect_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
