CREATE TABLE development_mutation_receipts (
  schema_id ANY NOT NULL CHECK (typeof(schema_id)='text' AND schema_id='governed-execution.nwp-development-mutation-receipt.v1'),
  mutation_ref ANY NOT NULL CHECK (typeof(mutation_ref)='text' AND length(mutation_ref) BETWEEN 1 AND 96 AND substr(mutation_ref,1,1) GLOB '[0-9A-Za-z]' AND mutation_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(mutation_ref,1,instr(mutation_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  mutation_family ANY NOT NULL CHECK (typeof(mutation_family)='text' AND mutation_family IN ('initialize_development_program','establish_development_author_effect_intent','establish_development_bound_effect_intent','ingest_development_source_observation','record_development_progression_decision')),
  command_schema_id ANY NOT NULL CHECK (typeof(command_schema_id)='text' AND command_schema_id IN ('governed-execution.nwp-initialize-development-program-command.v1','governed-execution.nwp-establish-development-author-effect-intent-command.v1','governed-execution.nwp-establish-development-bound-effect-intent-command.v1','governed-execution.nwp-ingest-development-source-observation-command.v1','governed-execution.nwp-record-development-progression-decision-command.v1')),
  command_digest ANY NOT NULL CHECK (typeof(command_digest)='text' AND length(command_digest)=64 AND command_digest=lower(command_digest) AND command_digest NOT GLOB '*[^0-9a-f]*'),
  program_ref ANY NOT NULL CHECK (typeof(program_ref)='text' AND length(program_ref) BETWEEN 1 AND 96 AND substr(program_ref,1,1) GLOB '[0-9A-Za-z]' AND program_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(program_ref,1,instr(program_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-')),
  decision_ref ANY CHECK (decision_ref IS NULL OR (typeof(decision_ref)='text' AND length(decision_ref) BETWEEN 1 AND 96 AND substr(decision_ref,1,1) GLOB '[0-9A-Za-z]' AND decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(decision_ref,1,instr(decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_program_version_ref ANY CHECK (result_program_version_ref IS NULL OR (typeof(result_program_version_ref)='text' AND length(result_program_version_ref) BETWEEN 1 AND 96 AND substr(result_program_version_ref,1,1) GLOB '[0-9A-Za-z]' AND result_program_version_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_program_version_ref,1,instr(result_program_version_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_semantic_attempt_ref ANY CHECK (result_semantic_attempt_ref IS NULL OR (typeof(result_semantic_attempt_ref)='text' AND length(result_semantic_attempt_ref) BETWEEN 1 AND 96 AND substr(result_semantic_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND result_semantic_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_semantic_attempt_ref,1,instr(result_semantic_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_effect_intent_ref ANY CHECK (result_effect_intent_ref IS NULL OR (typeof(result_effect_intent_ref)='text' AND length(result_effect_intent_ref) BETWEEN 1 AND 96 AND substr(result_effect_intent_ref,1,1) GLOB '[0-9A-Za-z]' AND result_effect_intent_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_effect_intent_ref,1,instr(result_effect_intent_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_effect_fence_ref ANY CHECK (result_effect_fence_ref IS NULL OR (typeof(result_effect_fence_ref)='text' AND length(result_effect_fence_ref) BETWEEN 1 AND 96 AND substr(result_effect_fence_ref,1,1) GLOB '[0-9A-Za-z]' AND result_effect_fence_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_effect_fence_ref,1,instr(result_effect_fence_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_delivery_attempt_ref ANY CHECK (result_delivery_attempt_ref IS NULL OR (typeof(result_delivery_attempt_ref)='text' AND length(result_delivery_attempt_ref) BETWEEN 1 AND 96 AND substr(result_delivery_attempt_ref,1,1) GLOB '[0-9A-Za-z]' AND result_delivery_attempt_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_delivery_attempt_ref,1,instr(result_delivery_attempt_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_observation_ref ANY CHECK (result_observation_ref IS NULL OR (typeof(result_observation_ref)='text' AND length(result_observation_ref) BETWEEN 1 AND 96 AND substr(result_observation_ref,1,1) GLOB '[0-9A-Za-z]' AND result_observation_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_observation_ref,1,instr(result_observation_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_decision_ref ANY CHECK (result_decision_ref IS NULL OR (typeof(result_decision_ref)='text' AND length(result_decision_ref) BETWEEN 1 AND 96 AND substr(result_decision_ref,1,1) GLOB '[0-9A-Za-z]' AND result_decision_ref NOT GLOB '*[^0-9A-Za-z.-]*' AND lower(substr(result_decision_ref,1,instr(result_decision_ref,'-'))) NOT IN ('connector-','tunnel-','workspace-','org-','organization-','user-'))),
  result_class ANY NOT NULL CHECK (typeof(result_class)='text' AND result_class IN ('development_program_initialized','development_author_effect_intent_established','development_bound_effect_intent_established','development_source_observation_ingested','development_progression_decision_recorded')),
  result_projection_digest ANY NOT NULL CHECK (typeof(result_projection_digest)='text' AND length(result_projection_digest)=64 AND result_projection_digest=lower(result_projection_digest) AND result_projection_digest NOT GLOB '*[^0-9a-f]*'),
  mutation_graph_digest ANY NOT NULL CHECK (typeof(mutation_graph_digest)='text' AND length(mutation_graph_digest)=64 AND mutation_graph_digest=lower(mutation_graph_digest) AND mutation_graph_digest NOT GLOB '*[^0-9a-f]*'),
  outcome ANY NOT NULL CHECK (typeof(outcome)='text' AND outcome='committed'),
  committed_at ANY NOT NULL CHECK (typeof(committed_at)='text' AND length(committed_at)=20 AND committed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr(committed_at,1,4) BETWEEN '0001' AND '9999' AND substr(committed_at,6,2) BETWEEN '01' AND '12' AND substr(committed_at,9,2) BETWEEN '01' AND '31' AND substr(committed_at,12,2) BETWEEN '00' AND '23' AND substr(committed_at,15,2) BETWEEN '00' AND '59' AND substr(committed_at,18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',committed_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',committed_at)=committed_at),
  PRIMARY KEY (mutation_ref),
  CONSTRAINT receipt_closed_family_algebra CHECK (((mutation_family='initialize_development_program' AND command_schema_id='governed-execution.nwp-initialize-development-program-command.v1' AND result_class='development_program_initialized' AND decision_ref IS NOT NULL AND result_program_version_ref IS NOT NULL AND result_semantic_attempt_ref IS NULL AND result_effect_intent_ref IS NULL AND result_effect_fence_ref IS NULL AND result_delivery_attempt_ref IS NULL AND result_observation_ref IS NULL AND result_decision_ref IS NOT NULL AND result_decision_ref=decision_ref) OR (mutation_family='establish_development_author_effect_intent' AND command_schema_id='governed-execution.nwp-establish-development-author-effect-intent-command.v1' AND result_class='development_author_effect_intent_established' AND decision_ref IS NOT NULL AND result_program_version_ref IS NOT NULL AND result_semantic_attempt_ref IS NOT NULL AND result_effect_intent_ref IS NOT NULL AND result_effect_fence_ref IS NOT NULL AND result_delivery_attempt_ref IS NOT NULL AND result_observation_ref IS NULL AND result_decision_ref IS NULL) OR (mutation_family='establish_development_bound_effect_intent' AND command_schema_id='governed-execution.nwp-establish-development-bound-effect-intent-command.v1' AND result_class='development_bound_effect_intent_established' AND decision_ref IS NOT NULL AND result_program_version_ref IS NOT NULL AND result_semantic_attempt_ref IS NOT NULL AND result_effect_intent_ref IS NOT NULL AND result_effect_fence_ref IS NOT NULL AND result_delivery_attempt_ref IS NOT NULL AND result_observation_ref IS NULL AND result_decision_ref IS NULL) OR (mutation_family='ingest_development_source_observation' AND command_schema_id='governed-execution.nwp-ingest-development-source-observation-command.v1' AND result_class='development_source_observation_ingested' AND decision_ref IS NULL AND result_program_version_ref IS NULL AND result_semantic_attempt_ref IS NULL AND result_effect_intent_ref IS NULL AND result_effect_fence_ref IS NULL AND result_delivery_attempt_ref IS NULL AND result_observation_ref IS NOT NULL AND result_decision_ref IS NULL) OR (mutation_family='record_development_progression_decision' AND command_schema_id='governed-execution.nwp-record-development-progression-decision-command.v1' AND result_class='development_progression_decision_recorded' AND decision_ref IS NOT NULL AND result_program_version_ref IS NOT NULL AND result_semantic_attempt_ref IS NULL AND result_effect_intent_ref IS NULL AND result_effect_fence_ref IS NULL AND result_delivery_attempt_ref IS NULL AND result_observation_ref IS NULL AND result_decision_ref IS NOT NULL AND result_decision_ref=decision_ref))),
  FOREIGN KEY (program_ref) REFERENCES development_program_heads (program_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, decision_ref) REFERENCES development_decisions (program_ref, decision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_program_version_ref) REFERENCES development_program_versions (program_ref, program_version_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_semantic_attempt_ref) REFERENCES development_semantic_attempts (program_ref, semantic_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_effect_intent_ref) REFERENCES development_effect_intents (program_ref, effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_effect_fence_ref) REFERENCES development_effect_fences (program_ref, effect_fence_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_delivery_attempt_ref) REFERENCES development_delivery_attempts (program_ref, delivery_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (program_ref, result_decision_ref) REFERENCES development_decisions (program_ref, decision_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

CREATE UNIQUE INDEX uq_development_effect_intents_author_command
ON development_effect_intents(command_ref)
WHERE effect_class = 'author_candidate';

